    memset(ph, 0, sizeof(ph));
    for (i = 0; i < n; i++) {
        double t = (double)i / fs;
        double acc = 0.0;
        double trem, p, gate;
        for (k = 0; k < 3; k++) {
            for (h = 1; h <= 3; h++) {
                ph[k][h - 1] += 2.0 * PI * notes[k] * (double)h / fs;
                if (ph[k][h - 1] > 2.0 * PI) ph[k][h - 1] -= 2.0 * PI;
