import re
data = open('/tmp/bs1770_streams.bin','rb').read()
start = data.find(b'0.1373291')
region = data[start-60000:start+120000].decode('latin-1')

pat = re.compile(r'1 0 0 1 ([\d.\-]+) ([\d.\-]+) Tm\s*\r?\n?0 g\s*\r?\n?0 G\s*\r?\n?\[((?:[^\[\]\\]|\\.)*)\]\s*TJ')
cells = {}
for m in pat.finditer(region):
    x, y = float(m.group(1)), float(m.group(2))
    parts = re.findall(r'\(((?:[^()\\]|\\.)*)\)', m.group(3))
    s = ''.join(parts).strip()
    if re.fullmatch(r'0\.\d+', s) and 330 < y < 550:
        cells[(round(y,1), int(x//100))] = s

ys = sorted(set(y for (y,c) in cells), reverse=True)
print('rows found:', len(ys), ys)

# fill grid: 12 rows x 4 phases; y step ~17.2. Missing cell = 0.
grid = {}
for y in ys:
    for c in range(4):
        v = cells.get((y, c))
        grid.setdefault(y, {})[c] = v
for y in ys:
    print(y, [grid[y].get(c) for c in range(4)])

